/// Slot `slot` of `node`, a node of `kind` (checked in safety builds).
fn @"ir.at"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot] else .nil;
}

/// The children of `node` from `slot` on.
fn @"ir.restAt"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) []const Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot..] else &.{};
}

fn @"ir.check"(node: Sexp, comptime kind: Tag, comptime what: []const u8) void {
    if (@import("builtin").optimize.runtimeSafety() and !node.isKind(kind)) {
        const actual = if (node.kind()) |k| @tagName(k) else @tagName(node);
        std.debug.panic(what ++ ": node is '{s}', not '" ++ @tagName(kind) ++ "'", .{actual});
    }
}


// =============================================================================
// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
/// The grammar has `@repair`: `parseTolerant` is available.
pub const hasRepair = false;
/// `@as` groups the promotable token may become (see `promote`).
const asGroups = 4;
const numSymbols = 298;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

inline fn tokenToSymbol(token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"ident" => needsPromotion,
        .@"integer" => 137,
        .@"zdigits" => 138,
        .@"newline" => 139,
        .@"comment" => 140,
        .@"indent" => 146,
        .@"sp" => 149,
        .@"spaces" => 150,
        .@"string" => 205,
        .@"patend" => 211,
        .@"quesat" => 213,
        .@"real" => 280,
        .@"notques" => 234,
        .@"noteq" => 235,
        .@"notlt" => 238,
        .@"notgt" => 239,
        .@"notlbracket" => 242,
        .@"notrbracket" => 243,
        .@"followseq" => 244,
        .@"sortsafter" => 245,
        .@"sortsaftereq" => 246,
        .@"notsortsafter" => 247,
        .@"eqeq" => 271,
        .@"notampersand" => 273,
        .@"notexclaim" => 274,
        .@"lparen" => 141,
        .@"comma" => 142,
        .@"rparen" => 145,
        .@"dot" => 148,
        .@"colon" => 151,
        .@"at" => 154,
        .@"eq" => 155,
        .@"dollar" => 157,
        .@"plus" => 178,
        .@"caret" => 179,
        .@"pipe" => 188,
        .@"lbracket" => 189,
        .@"rbracket" => 190,
        .@"slash" => 202,
        .@"star" => 203,
        .@"hash" => 204,
        .@"exclaim" => 209,
        .@"question" => 210,
        .@"minus" => 220,
        .@"lt" => 236,
        .@"gt" => 237,
        .@"not" => 267,
        .@"underscore" => 268,
        .@"backslash" => 269,
        .@"ampersand" => 272,
        .@"lteq" => 240,
        .@"gteq" => 241,
        .@"starstar" => 270,
        else => 2, // error
    };
}

fn promote(self: *BaseParser, token: Token) u16 {
    // The ordinal of a match made in an earlier state (before a
    // reduction) is not this match's.
    self.lastMatchedId = 0;
    const text = self.source[token.pos..][0..token.len];
    if (text.len == 0) return promotableSymbol;
    if (self.tryPromote(0, text, fnAs, &fnToSymbol, fnFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(1, text, isvAs, &isvToSymbol, isvFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(2, text, ssvnAs, &ssvnToSymbol, ssvnFallbackSymbol, false)) |sym| return sym;
    if (getAction(self.stateStack.last().?, promotableSymbol) != 0) return promotableSymbol;
    if (self.tryPromote(3, text, cmdAs, &cmdToSymbol, cmdFallbackSymbol, true)) |sym| return sym;
    return promotableSymbol;
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    return switch (ruleId) {
        3 => blk: { const out = self.allocItems(1 + pass[0].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"routine" }; n += 1; @memcpy(out[n..][0..pass[0].items().len], pass[0].items()); n += pass[0].items().len; break :blk self.finishItems(out, .tree); },
        4 => self.buildOf(&.{ .nil }, pass, .spread, false),
        5 => self.buildOf(&.{ .{ .elem = 0 } }, pass, .spread, false),
        6 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = .nil; n += 1; break :blk self.keepExtended(out, n, pass, 0, .spread, false); },
        7 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[2]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .spread, false); },
        8 => blk: { const out = self.allocItems(1 + pass[0].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"commands" }; n += 1; @memcpy(out[n..][0..pass[0].items().len], pass[0].items()); n += pass[0].items().len; break :blk self.finishItems(out, .tree); },
        9 => blk: { const out = self.allocItems(1 + pass[0].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"commands" }; n += 1; @memcpy(out[n..][0..pass[0].items().len], pass[0].items()); n += pass[0].items().len; break :blk self.finishItems(out, .tree); },
        10 => self.buildOf(&.{ .{ .tag = .@"commands" }, .{ .elem = 0 } }, pass, .tree, false),
        16 => self.buildOf(&.{ .{ .tag = .@"label" }, .{ .elem = 0 }, .nil, .nil }, pass, .tree, false),
        17 => self.buildOf(&.{ .{ .tag = .@"label" }, .{ .elem = 0 }, .{ .elem = 1 }, .nil }, pass, .tree, false),
        18 => self.buildOf(&.{ .{ .tag = .@"label" }, .{ .elem = 0 }, .nil, .nil }, pass, .tree, false),
        19 => self.buildOf(&.{ .{ .tag = .@"label" }, .{ .elem = 0 }, .{ .elem = 1 }, .nil }, pass, .tree, false),
        20 => blk: { const out = self.allocItems(4 + pass[2].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"label" }; n += 1; out[n] = pass[0]; n += 1; out[n] = .nil; n += 1; out[n] = .nil; n += 1; @memcpy(out[n..][0..pass[2].items().len], pass[2].items()); n += pass[2].items().len; break :blk self.finishItems(out, .tree); },
        21 => blk: { const out = self.allocItems(4 + pass[3].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"label" }; n += 1; out[n] = pass[0]; n += 1; out[n] = pass[1]; n += 1; out[n] = .nil; n += 1; @memcpy(out[n..][0..pass[3].items().len], pass[3].items()); n += pass[3].items().len; break :blk self.finishItems(out, .tree); },
        22 => self.buildOf(&.{ .{ .tag = .@"label" }, .{ .elem = 0 }, .nil, .{ .elem = 2 } }, pass, .tree, false),
        23 => blk: { const out = self.allocItems(4 + pass[3].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"label" }; n += 1; out[n] = pass[0]; n += 1; out[n] = .nil; n += 1; out[n] = pass[2]; n += 1; @memcpy(out[n..][0..pass[3].items().len], pass[3].items()); n += pass[3].items().len; break :blk self.finishItems(out, .tree); },
        24 => self.buildOf(&.{ .{ .elem = 0 } }, pass, .tree, false),
        25 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[2]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .tree, true); },
        29 => self.buildOf(&.{ .{ .tag = .@"line" }, .{ .elem = 0 } }, pass, .tree, false),
        30 => blk: { const out = self.allocItems(2 + pass[1].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"line" }; n += 1; out[n] = pass[0]; n += 1; @memcpy(out[n..][0..pass[1].items().len], pass[1].items()); n += pass[1].items().len; break :blk self.finishItems(out, .tree); },
        31 => self.buildOf(&.{ .{ .elem = 0 } }, pass, .tree, false),
        32 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[1]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .tree, true); },
        75 => self.buildOf(&.{ .{ .elem = 0 } }, pass, .spread, false),
        76 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[2]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .spread, false); },
        79 => self.buildOf(&.{ .{ .tag = .@"postcond" }, .{ .elem = 1 } }, pass, .tree, false),
        80 => self.buildOf(&.{ .{ .elem = 0 } }, pass, .spread, false),
        81 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[2]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .spread, true); },
        82 => blk: { const out = self.allocItems(2 + pass[2].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"set" }; n += 1; out[n] = .nil; n += 1; @memcpy(out[n..][0..pass[2].items().len], pass[2].items()); n += pass[2].items().len; break :blk self.finishItems(out, .tree); },
        83 => blk: { const out = self.allocItems(2 + pass[3].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"set" }; n += 1; out[n] = pass[1]; n += 1; @memcpy(out[n..][0..pass[3].items().len], pass[3].items()); n += pass[3].items().len; break :blk self.finishItems(out, .tree); },
        84 => self.build(&.{ .{ .tag = .@"=" }, self.nested(self.buildOf(&.{ .{ .tag = .@"@name" }, .{ .elem = 1 } }, pass, .tree, false), 1, 1), pass[3] }, .tree),
        85 => self.buildOf(&.{ .{ .tag = .@"@args" }, .{ .elem = 1 } }, pass, .tree, false),
        86 => self.buildOf(&.{ .{ .tag = .@"=" }, .{ .elem = 0 }, .{ .elem = 2 } }, pass, .tree, false),
