/// First slot of rest role `role` in nodes of `kind`.
fn restSlotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"routine" => if (role == .@"lines") 1 else null,
        .@"label" => if (role == .@"cmds") 4 else null,
        .@"line" => if (role == .@"cmds") 2 else null,
        .@"commands" => if (role == .@"cmds") 1 else null,
        .@"set" => if (role == .@"args") 2 else null,
        .@"new" => if (role == .@"args") 2 else null,
        .@"kill" => if (role == .@"args") 2 else null,
        .@"merge" => if (role == .@"args") 2 else null,
        .@"do" => if (role == .@"args") 2 else null,
        .@"goto" => if (role == .@"args") 2 else null,
        .@"break" => if (role == .@"args") 2 else null,
        .@"hang" => if (role == .@"args") 2 else null,
        .@"job" => if (role == .@"args") 2 else null,
        .@"xecute" => if (role == .@"args") 2 else null,
        .@"view" => if (role == .@"args") 2 else null,
        .@"open" => if (role == .@"args") 2 else null,
        .@"use" => if (role == .@"args") 2 else null,
        .@"read" => if (role == .@"args") 2 else null,
        .@"write" => if (role == .@"args") 2 else null,
        .@"close" => if (role == .@"args") 2 else null,
        .@"lock" => if (role == .@"args") 2 else null,
        .@"zwrite" => if (role == .@"args") 2 else null,
        .@"zbreak" => if (role == .@"args") 2 else null,
        .@"zkill" => if (role == .@"args") 2 else null,
        .@"zlink" => if (role == .@"args") 2 else null,
        .@"zsystem" => if (role == .@"args") 2 else null,
        .@"zshow" => if (role == .@"args") 2 else null,
        .@"zsave" => if (role == .@"args") 2 else null,
        .@"zinsert" => if (role == .@"args") 2 else null,
        .@"zremove" => if (role == .@"args") 2 else null,
        .@"zprint" => if (role == .@"args") 2 else null,
        .@"if" => if (role == .@"conds") 1 else null,
        .@"for" => if (role == .@"params") 2 else null,
        .@"setmulti" => if (role == .@"targets") 2 else null,
        .@"setfn" => if (role == .@"args") 3 else null,
        .@"exclusive" => if (role == .@"names") 1 else null,
        .@"control" => if (role == .@"args") 2 else null,
        .@"posformat" => if (role == .@"marks") 2 else null,
        .@"lock=" => if (role == .@"refs") 2 else null,
        .@"lock+" => if (role == .@"refs") 2 else null,
        .@"lock-" => if (role == .@"refs") 2 else null,
        .@"vars" => if (role == .@"names") 1 else null,
        .@"zwarg" => if (role == .@"suffixes") 2 else null,
        .@"expr" => if (role == .@"tails") 2 else null,
        .@"naked" => if (role == .@"subs") 1 else null,
        .@"select" => if (role == .@"cases") 1 else null,
        .@"pat" => if (role == .@"alts") 5 else null,
        else => null,
    };
}

